namespace ZapretGui;
sealed partial class MainForm {
 void BuildFeatures(TabControl tabs,Control manage){ BuildTests(tabs); BuildSettings(tabs); BuildUpdates(tabs);
  AsyncButton(manage,"Применить стратегию к службе",()=>Backend.Install(root.Text,strategies.Text));
  AsyncButton(manage,"Удалить службу",()=>Backend.Power("$s=Get-Service zapret;Stop-Service zapret;$s.WaitForStatus('Stopped',[TimeSpan]::FromSeconds(20));sc.exe delete zapret;if($LASTEXITCODE){throw 'Ошибка удаления'}",true),confirm:true);
  var diag=Page(tabs,"Диагностика");AsyncButton(diag,"Проверить систему",CheckSystemCards);
  AsyncButton(diag,"Перенести WinDivert в выбранную папку",()=>Backend.Power("$path="+Backend.Quote(Path.Combine(root.Text,"bin/WinDivert64.sys"))+";"+"""$new='\??\'+$path;if(!(Test-Path -LiteralPath $path)){throw 'Driver missing'};$key='HKLM:\SYSTEM\CurrentControlSet\Services\WinDivert';$old=(Get-ItemProperty $key).ImagePath;$s=Get-Service zapret;$running=$s.Status -eq 'Running';try{if($running){Stop-Service zapret;$s.WaitForStatus('Stopped',[TimeSpan]::FromSeconds(20))};$state= & sc.exe query WinDivert 2>&1;if($LASTEXITCODE){throw ($state -join ' ')};if(($state -join ' ') -notmatch 'STATE\s*:\s*1\s'){$stopOutput= & sc.exe stop WinDivert 2>&1;if($LASTEXITCODE){throw ($stopOutput -join ' ')};$deadline=[DateTime]::UtcNow.AddSeconds(20);do{$q= & sc.exe query WinDivert 2>&1;$code=$LASTEXITCODE;if($code -eq 1060){break};if($code){throw ($q -join ' ')};if(($q -join ' ') -match 'STATE\s*:\s*1\s'){break};if([DateTime]::UtcNow -ge $deadline){throw 'WinDivert stop timed out'};Start-Sleep -Milliseconds 250}while($true)};sc.exe config WinDivert binPath= $new;$configCode=$LASTEXITCODE;if($configCode -eq 1060){sc.exe create WinDivert type= kernel start= demand error= normal binPath= $new;if($LASTEXITCODE){throw 'Driver create failed'}}elseif($configCode){throw 'Driver config failed'};if($running){Start-Service zapret};Get-CimInstance Win32_SystemDriver -Filter "Name='WinDivert'" | Format-List Name,State,PathName}catch{$failure=$_;sc.exe config WinDivert binPath= $old;if($running){Start-Service zapret -ErrorAction Continue};throw $failure}""",true));
  AsyncButton(diag,"Включить TCP timestamps",()=>Backend.Power("netsh interface tcp set global timestamps=enabled;if($LASTEXITCODE){throw 'Ошибка netsh'}",true));

 }
 FlowLayoutPanel Page(TabControl tabs,string title){var page=new TabPage(title);tabs.TabPages.Add(page);var p=new FlowLayoutPanel(){Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,AutoScroll=false};page.Controls.Add(p);return p;}
 void AsyncButton(Control parent,string title,Func<Task<string>> action,bool confirm=false){var b=new PillButton(){Text=title,AutoSize=true};parent.Controls.Add(b);b.Click+=async(_,_)=>{if(confirm&&MessageBox.Show(this,"Удалить службу Zapret?","Удаление службы",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning)!=DialogResult.OK)return;b.Enabled=false;ActionOutput(b,"Выполняется: "+title+"…");try{ActionOutput(b,await action());}catch(Exception e){ActionOutput(b,e.Message);}finally{b.Enabled=true;}};}
}
